// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("campaign_performance",
			mcplib.WithDescription("Read a campaign and its authoritative performance counters, optionally including costly link statistics. Returns stats; for offline cohort and resend decisions use workflow campaign-review. Read-only; two API calls. Get a specific campaign. Then Returns sent count and open/click/bounce/unsubscribe/spam counts and rates, all read from stored counters. Pass `include_link_stats=true` to also get `link_stats` — the campaign's links ranked by click count. That part is opt-in because it counts rows in `email_link_clicks` once per link rather than reading a counter, so leaving it off keeps this endpoint as cheap as it has always been."),
			mcplib.WithNumber("campaign_id", mcplib.Required(), mcplib.Description("ID of the campaign to inspect.")),
			mcplib.WithBoolean("include_links", mcplib.Description("Include optional link-level counters, increasing server work.")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithIdempotentHintAnnotation(true),
			mcplib.WithOpenWorldHintAnnotation(true),
		),
		handleCampaignPerformance,
	)
}

// handleCampaignPerformance runs the campaign_performance intent: Read a campaign and its authoritative performance counters, optionally including costly link statistics. Returns stats; for offline cohort and resend decisions use workflow campaign-review. Read-only; two API calls. Get a specific campaign. Then Returns sent count and open/click/bounce/unsubscribe/spam counts and rates, all read from stored counters. Pass `include_link_stats=true` to also get `link_stats` — the campaign's links ranked by click count. That part is opt-in because it counts rows in `email_link_clicks` once per link rather than reading a counter, so leaving it off keeps this endpoint as cheap as it has always been.
