	if input == nil {
		input = map[string]any{}
	}
	if err := cli.AdoptMCPOutputSemantics(platformSession, input); err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	scope := map[string]any{"input": input}

	// Step 1: campaigns.get
	{
		params := map[string]any{}
		if v, ok := resolveIntentBinding(scope, "${input.campaign_id}"); ok {
			params["id"] = v
		}
		resp, err := callIntentEndpoint(ctx, c, "campaigns.get", params)
		if err != nil {
			return mcplib.NewToolResultError(fmt.Sprintf("step %d (campaigns.get) failed: %v", 1, err)), nil
		}
		scope["campaign"] = resp
	}

	// Step 2: campaigns.get-stats
	{
		params := map[string]any{}
		if v, ok := resolveIntentBinding(scope, "${campaign.id}"); ok {
			params["id"] = v
		}
		if v, ok := resolveIntentBinding(scope, "${input.include_links}"); ok {
			params["include_link_stats"] = v
		}
		resp, err := callIntentEndpoint(ctx, c, "campaigns.get-stats", params)
		if err != nil {
			return mcplib.NewToolResultError(fmt.Sprintf("step %d (campaigns.get-stats) failed: %v", 2, err)), nil
		}
		scope["stats"] = resp
	}

	returnKey := "stats"
	if returnKey == "" {
		returnKey = "stats"
	}

	if returnKey == "" {
		text := `{"status":"ok"}`
		if platformSession != nil {
			text = bound.WithMetadata(text, platformSession.OutputMetadata())
		}
		return mcplib.NewToolResultText(text), nil
	}
	out := scope[returnKey]
	text, err := bound.JSON(out)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding %s result: %v", returnKey, err)), nil
	}
	if platformSession != nil {
		text = bound.WithMetadata(text, platformSession.OutputMetadata())
	}
